import ast
import datetime
import json
import os
from pathlib import Path
import sys
import time
sys.dont_write_bytecode = True
sys.path.insert(0, str(Path.cwd() / 'scripts/aws'))
from aws_cli import run, result

OUT = Path('testdata/aws/cloudwatch/metric_search_windows.json')
BASE = json.loads(Path('testdata/aws/cloudwatch/metric_search.json').read_text())
NS = BASE['namespace']
ANCHOR = BASE['anchor_seconds']
REGION = 'us-west-2'
ACCOUNT = '000000000000'
ENV = dict(os.environ, AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_MAX_ATTEMPTS='1', AWS_RETRY_MODE='standard', AWS_PAGER='', AWS_IGNORE_CONFIGURED_ENDPOINT_URLS='true')
for key in list(ENV):
    if key.startswith('AWS_ENDPOINT_URL'):
        del ENV[key]
METRICS = {r['metric']['MetricName']: r['metric'] for r in BASE['cleanup']['retained_metrics'] if r['metric']['MetricName'] in ('SDBFailure', 'Network-Errors_2')}
NAMES = ['SDBFailure', 'Network-Errors_2']
cap = json.loads(OUT.read_text()) if OUT.exists() else {
    'region': REGION, 'caller_account': ACCOUNT, 'namespace': NS, 'anchor_seconds': ANCHOR,
    'sources': [], 'primary_references': BASE['primary_references'],
    'source_fixture': {'path': 'testdata/aws/cloudwatch/metric_search.json', 'observation_labels': ['publish-owned-metrics', 'final-direct-control', 'final-search-control', 'control-page-single-2', 'control-page-direct', 'control-page-direct-next-4', 'control-page-59']},
    'known_metrics': [{'metric': METRICS[NAMES[0]], 'timestamps': [ANCHOR, ANCHOR+120], 'sums': [212,220]}, {'metric': METRICS[NAMES[1]], 'timestamps': [ANCHOR, ANCHOR+180], 'sums': [252,264]}],
    'observations': [], 'pagination_chains': [],
    'cleanup': {'resources_created': [], 'metrics_published': False, 'configuration_modified': False, 'credentials_persisted': False}
}
source = {'path': __file__, 'content': Path(__file__).read_text()}
if source not in cap['sources']:
    cap['sources'].append(source)
if not any(r['path'] == 'scripts/aws/aws_cli.py' for r in cap['sources']):
    cap['sources'].append({'path': 'scripts/aws/aws_cli.py', 'content': Path('scripts/aws/aws_cli.py').read_text()})

def save():
    OUT.write_text(json.dumps(cap, indent=2) + '\n')

def request(label, operation, parameters, service='cloudwatch'):
    started = time.time_ns() // 1000000
    proc = run(service, operation, parameters, ENV, options=['--debug', '--no-paginate', '--cli-connect-timeout', '5', '--cli-read-timeout', '30'], timeout=45)
    res = result(proc, debug=True)
    for line in proc.stderr.splitlines():
        if 'Response headers:' in line:
            try:
                headers = ast.literal_eval(line.split('Response headers:', 1)[1].strip())
                for key, value in headers.items():
                    if key.lower() in ('x-amzn-requestid', 'x-amzn-request-id', 'x-amz-request-id'):
                        res['request_id'] = value
            except (ValueError, SyntaxError):
                pass
        if line.startswith(("b'{", 'b"{')):
            try:
                raw = ast.literal_eval(line).decode('utf-8')
                res['raw_response'] = raw
                res['output'] = json.loads(raw)
            except (ValueError, SyntaxError):
                pass
    if service == 'sts' and res['code'] == 'Success':
        cap['actor_arn'] = res['output']['Arn']
    cap['observations'].append({'label': label, 'service': service, 'operation': operation, 'input': parameters, 'region': REGION, 'caller_account': ACCOUNT, 'actor_arn': cap.get('actor_arn', ''), 'request_started_ms': started, 'result': res})
    save()
    print(label, res['code'], [(r['Id'],r['Label'],r['StatusCode'],r['Timestamps'],r['Values']) for r in res.get('output',{}).get('MetricDataResults',[])], 'token='+str(bool(res.get('output',{}).get('NextToken'))), flush=True)
    return res

def guard(phase):
    ident = request('identity-'+phase, 'get-caller-identity', {}, 'sts')
    assert ident['code'] == 'Success' and ident['output']['Account'] == ACCOUNT and ident['output']['Arn'] == 'arn:aws:iam::000000000000:user/Delegated'

def search(count=1, period=60):
    term = 'Namespace="'+NS+'" AND ('+' OR '.join('MetricName="'+name+'"' for name in NAMES[:count])+')'
    return "SEARCH('"+term+"', 'Sum'"+('' if period is None else ', '+str(period))+')'

def direct(index=0, hidden=False):
    return {'Id': 'm'+str(index+1), 'MetricStat': {'Metric': METRICS[NAMES[index]], 'Period':60, 'Stat':'Sum'}, **({'ReturnData': False} if hidden else {})}

def expr(expression, id='e', **kwargs):
    return {'Id':id, 'Expression':expression, **kwargs}

def query(label, queries, budget=100, scan='TimestampAscending', start=-60, end=300, follow=True):
    stamp = lambda sec: datetime.datetime.fromtimestamp(ANCHOR+sec, datetime.timezone.utc).isoformat().replace('+00:00','Z')
    params = {'StartTime':stamp(start), 'EndTime':stamp(end), 'ScanBy':scan, 'MetricDataQueries':queries, 'MaxDatapoints':budget}
    res = request(label, 'get-metric-data', params)
    labels = [label]
    token = res.get('output',{}).get('NextToken')
    while follow and token:
        params = {**params, 'NextToken':token}
        page_label = label+'-next-'+str(len(labels))
        res = request(page_label, 'get-metric-data', params)
        labels.append(page_label)
        assert res['code'] == 'Success', 'Native pagination failed'
        token = res.get('output',{}).get('NextToken')
        assert len(labels) < 100, 'Unexpected unbounded pagination'
    if len(labels)>1:
        cap['pagination_chains'].append({'initial_label':label,'page_labels':labels,'exhausted':not bool(token)})
        save()
    return res

def main():
    phase = sys.argv[1]
    guard(phase)
    if phase == 'initial':
        query('positive-direct-two', [direct(0),direct(1)])
        query('positive-search-one', [expr(search(1))])
        query('positive-search-two', [expr(search(2))])
        for period in [0.5,1,1.5,2,2.5,5,5.5,6,30,30.5,31,59,59.5,60,60.5,60.9,61,61.5,119,119.9,120,120.5]:
            query('fraction-'+str(period), [expr(search(1,period))], budget=1000)
        for period in [60,120]:
            query('inherit-'+str(period), [expr(search(1,None),Period=period)])
        query('fraction-explicit-60.5-query-120', [expr(search(1,60.5),Period=120)])
        query('fraction-explicit-120.5-query-60', [expr(search(1,120.5),Period=60)])
        cases = {
            'direct-one':[direct()], 'direct-two':[direct(0),direct(1)],
            'search-one':[expr(search())], 'search-two':[expr(search(2))],
            'hidden-search-sum':[expr(search(2),'hidden',ReturnData=False),expr('SUM(hidden)','total')],
            'sum-inline':[expr('SUM('+search(2)+')')],
            'mixed':[direct(),expr(search(2))],
            'hidden-direct-sum':[direct(0,True),direct(1,True),expr('m1+m2')],
            'hidden-unused-search':[direct(),expr(search(2),'hidden',ReturnData=False)],
        }
        for scan in ['TimestampAscending','TimestampDescending']:
            for name, queries in cases.items():
                for budget in [1,2,3,12]:
                    query('window-'+name+'-'+scan+'-max-'+str(budget),queries,budget,scan)
    else:
        raise ValueError(phase)

if __name__ == '__main__':
    main()

"""AWS CLI transport shared by native behavior probes.

Callers own endpoint/retry choices, observations and resource cleanup. JSON shapes
remain open because probes deliberately exercise invalid and newly added inputs.
"""
import ast
import json
import re
import subprocess
from collections.abc import Mapping, Sequence
from typing import Any, NotRequired, TypedDict


class ProbeResult(TypedDict):
    code: str
    output: NotRequired[dict[str, Any]]
    error: NotRequired[dict[str, Any]]
    message: NotRequired[str]
    http_status: NotRequired[int]


class CLITimeout(RuntimeError):
    """A bounded CLI call expired; command arguments may contain secrets."""


class AWSCLIError(RuntimeError):
    """A failed strict call, retaining native JSON error fields for its caller."""

    def __init__(self, service: str, operation: str, stderr: str, details: dict[str, Any]):
        super().__init__(f"{service}:{operation}: {stderr.strip()}")
        self.details = details


def run(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
        env: Mapping[str, str] | None = None, *, options: Sequence[str] = (),
        timeout: float | None = None) -> subprocess.CompletedProcess[str]:
    """Execute one CLI command without interpreting service or client failures."""
    command = ["aws", service, operation, "--output", "json", "--no-cli-pager"]
    if parameters is not None:
        command += ["--cli-input-json", json.dumps(parameters)]
    try:
        return subprocess.run(command + list(options), env=env, capture_output=True,
                              text=True, check=False, timeout=timeout)
    except subprocess.TimeoutExpired:
        raise CLITimeout("AWS CLI timed out during " + operation) from None


def call(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
         env: Mapping[str, str] | None = None, *, paginate: bool = True,
         error_format: str | None = None) -> dict[str, Any]:
    """Return JSON output; service and CLI-validation errors retain typed details.

    Configuration and transport failures abort capture instead of becoming
    observations of AWS behavior. AWS CLI uses 252 for input errors and 254
    for service errors.
    """
    options = ["--cli-connect-timeout", "10", "--cli-read-timeout", "30"]
    if error_format is not None:
        options += ["--cli-error-format", error_format]
    if not paginate:
        options.append("--no-paginate")
    process = run(service, operation, parameters or None, env, options=options)
    if process.returncode:
        diagnosis = f"{service}:{operation}: {process.stderr.strip()}"
        if error_format == "json" and process.returncode in (252, 254):
            try:
                details = json.loads(process.stderr)
            except json.JSONDecodeError:
                raise RuntimeError(diagnosis) from None
            if isinstance(details, dict) and isinstance(details.get("Code"), str):
                raise AWSCLIError(service, operation, process.stderr, details)
        raise RuntimeError(diagnosis)
    return result(process)["output"]


def observe(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
            env: Mapping[str, str] | None = None, *, paginate: bool = True) -> ProbeResult:
    """Capture native JSON success/error fields; callers own output redaction."""
    try:
        output = call(service, operation, parameters, env, paginate=paginate, error_format="json")
    except AWSCLIError as error:
        return {"code": error.details["Code"], "error": error.details}
    return {"code": "Success", "output": output}


def _text_error(stderr: str) -> tuple[str, str | None]:
    match = re.search(r"An error occurred \(([^)]+)\)(?:.*?operation(?: \([^)]*\))?: (.*))?", stderr)
    return (match[1], match[2]) if match else ("CLIError", None)


def result(process: subprocess.CompletedProcess[str], *, cli_error: str = "CLIError",
           cli_message: str | None = "AWS CLI failed; raw diagnostics discarded",
           debug: bool = False) -> ProbeResult:
    """Decode an observation, separating modeled errors from CLI rejection.

    A None client message retains the final three diagnostic lines for probes
    whose captured CLI-validation observations include those lines.
    """
    if process.returncode:
        code, message = _text_error(process.stderr)
        decoded: ProbeResult = {
            "code": code if message is not None else cli_error,
            "message": message if message is not None else cli_message if cli_message is not None
            else " ".join(process.stderr.splitlines()[-3:]),
        }
    else:
        decoded = {"code": "Success", "output": json.loads(process.stdout) if process.stdout.strip() else {}}
    if debug:
        statuses = re.findall(r'"[A-Z]+ [^"\r\n]* HTTP/1\.[01]" (\d{3})', process.stderr)
        if statuses:
            decoded["http_status"] = int(statuses[-1])
    return decoded


def error_code(process: subprocess.CompletedProcess[str]) -> str:
    """Decode code-only observations, including CLI ParamValidation errors."""
    return _text_error(process.stderr)[0]


def raw_xml(process: subprocess.CompletedProcess[str]) -> bytes | None:
    """Extract the last XML response from CLI debug output; discard other logs."""
    raw = None
    for line in process.stderr.splitlines():
        if line.startswith(("b'<", 'b"<')):
            try:
                candidate = ast.literal_eval(line)
                if candidate.startswith(b"<"):
                    raw = candidate
            except (ValueError, SyntaxError):
                pass
    return raw
